        this.emailInput = document.getElementById('email');
        this.phoneInput = document.getElementById('phone');
        this.successMessage = document.getElementById('successMessage');

        this.fieldStates = {
            fullName: { touched: false, valid: false },
            email: { touched: false, valid: false },
            phone: { touched: false, valid: false }
        };

        this.initializeEventListeners();
    }

    initializeEventListeners() {
        this.form.addEventListener('submit', (e) => this.handleSubmit(e));

        this.fullNameInput.addEventListener('blur', () => this.validateField('fullName'));
        this.emailInput.addEventListener('blur', () => this.validateField('email'));
        this.phoneInput.addEventListener('blur', () => this.validateField('phone'));

        this.fullNameInput.addEventListener('input', () => this.markTouched('fullName'));
        this.emailInput.addEventListener('input', () => this.markTouched('email'));
        this.phoneInput.addEventListener('input', () => this.markTouched('phone'));
    }

    markTouched(fieldName) {
        this.fieldStates[fieldName].touched = true;
    }

    validateField(fieldName) {
        const validators = {
            fullName: () => {
                const value = this.fullNameInput.value.trim();
                return value.length > 0;
            },
            email: () => {
                const value = this.emailInput.value.trim();
                const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
                return emailRegex.test(value);
            },
            phone: () => {
                const value = this.phoneInput.value.trim();
                if (value.length === 0) return true;
                const phoneRegex = /^[\d\s\-()+.]*$|^[\d\s().\-]{10,}$/;
                return phoneRegex.test(value) && /\d/.test(value);
            }
        };

        const isValid = validators[fieldName]();
        this.fieldStates[fieldName].valid = isValid;
        this.updateFieldDisplay(fieldName, isValid);
        return isValid;
    }

    updateFieldDisplay(fieldName, isValid) {
        const inputMap = {
            fullName: this.fullNameInput,
            email: this.emailInput,
            phone: this.phoneInput
        };

        const errorMap = {
            fullName: document.getElementById('fullNameError'),
            email: document.getElementById('emailError'),
            phone: document.getElementById('phoneError')
        };

        const input = inputMap[fieldName];
        const errorDiv = errorMap[fieldName];

        if (this.fieldStates[fieldName].touched) {
            if (isValid) {
                input.setAttribute('aria-invalid', 'false');
                errorDiv.textContent = '';
            } else {
                input.setAttribute('aria-invalid', 'true');
                this.setErrorMessage(fieldName, errorDiv);
            }
        } else {
            input.setAttribute('aria-invalid', 'false');
            errorDiv.textContent = '';
        }
    }

    setErrorMessage(fieldName, errorDiv) {
        const messages = {
            fullName: 'Please enter your full name.',
            email: 'Please enter a valid email address.',
            phone: 'Please enter a valid phone number.'
        };
        errorDiv.textContent = messages[fieldName];
    }

    handleSubmit(e) {
        e.preventDefault();

        const fullNameValid = this.validateField('fullName');
        const emailValid = this.validateField('email');
        const phoneValid = this.validateField('phone');

        this.fieldStates.fullName.touched = true;
        this.fieldStates.email.touched = true;
        this.fieldStates.phone.touched = true;

        if (fullNameValid && emailValid && phoneValid) {
            this.submitForm();
        } else {
            const firstInvalidField = !fullNameValid ? this.fullNameInput : (!emailValid ? this.emailInput : this.phoneInput);
            firstInvalidField.focus();
        }
    }

    submitForm() {
        const formData = {
            fullName: this.fullNameInput.value.trim(),
            email: this.emailInput.value.trim(),
            phone: this.phoneInput.value.trim()
        };

        console.log('Form submitted:', formData);

        this.form.reset();
        this.fieldStates = {
            fullName: { touched: false, valid: false },
            email: { touched: false, valid: false },
            phone: { touched: false, valid: false }
        };

        this.clearAllErrors();
        this.showSuccessMessage();
    }

    clearAllErrors() {
        document.getElementById('fullNameError').textContent = '';
        document.getElementById('emailError').textContent = '';
        document.getElementById('phoneError').textContent = '';

        this.fullNameInput.setAttribute('aria-invalid', 'false');
        this.emailInput.setAttribute('aria-invalid', 'false');
        this.phoneInput.setAttribute('aria-invalid', 'false');
    }

    showSuccessMessage() {
        this.successMessage.setAttribute('aria-hidden', 'false');

        setTimeout(() => {
            this.successMessage.setAttribute('aria-hidden', 'true');
        }, 5000);
    }
}

document.addEventListener('DOMContentLoaded', () => {
    new ContactForm();
});
